   404    bool subset (hb_subset_context_t *c) const
   405    {
   406      TRACE_SUBSET (this);
   407
   408      gvar *out = c->serializer->allocate_min<gvar> ();
   409      if (unlikely (!out)) return_trace (false);
   410
   411      out->version.major = 1;
   412      out->version.minor = 0;
   413      out->axisCount = axisCount;
   414      out->sharedTupleCount = sharedTupleCount;
   415
   416      unsigned int num_glyphs = c->plan->num_output_glyphs ();
   417      out->glyphCount = num_glyphs;
   418
   419      unsigned int subset_data_size = 0;
   420      for (hb_codepoint_t gid = 0; gid < num_glyphs; gid++)
   421      {
   422        hb_codepoint_t old_gid;
   423        if (!c->plan->old_gid_for_new_gid (gid, &old_gid)) continue;
   424        subset_data_size += get_glyph_var_data_length (old_gid);
   425      }
   426
   427      bool long_offset = subset_data_size & ~0xFFFFu;
   428      out->flags = long_offset ? 1 : 0;
   429
   430      HBUINT8 *subset_offsets = c->serializer->allocate_size<HBUINT8> ((long_offset ? 4 : 2) * (num_glyphs + 1));
   431      if (!subset_offsets) return_trace (false);
   432
   433      /* shared tuples */
   434      if (!sharedTupleCount || !sharedTuples)
   435        out->sharedTuples = 0;
   436      else
   437      {
   438        unsigned int shared_tuple_size = F2DOT14::static_size * axisCount * sharedTupleCount;
   439        F2DOT14 *tuples = c->serializer->allocate_size<F2DOT14> (shared_tuple_size);
   440        if (!tuples) return_trace (false);
   441        out->sharedTuples = (char *) tuples - (char *) out;
   442        memcpy (tuples, &(this+sharedTuples), shared_tuple_size);
   443      }
   444
   445      char *subset_data = c->serializer->allocate_size<char> (subset_data_size);
   446      if (!subset_data) return_trace (false);
   447      out->dataZ = subset_data - (char *)out;
   448
   449      unsigned int glyph_offset = 0;
   450      for (hb_codepoint_t gid = 0; gid < num_glyphs; gid++)
   451      {
   452        hb_codepoint_t old_gid;
   453        unsigned int length = c->plan->old_gid_for_new_gid (gid, &old_gid) ? get_glyph_var_data_length (old_gid) : 0;
   454
   455        if (long_offset)
   456          ((HBUINT32 *) subset_offsets)[gid] = glyph_offset;
   457        else
   458          ((HBUINT16 *) subset_offsets)[gid] = glyph_offset / 2;
   459
   460        if (length > 0) memcpy (subset_data, &get_glyph_var_data (old_gid), length);
   461        subset_data += length;
   462        glyph_offset += length;
   463      }
   464      if (long_offset)
   465        ((HBUINT32 *) subset_offsets)[num_glyphs] = glyph_offset;
   466      else
   467        ((HBUINT16 *) subset_offsets)[num_glyphs] = glyph_offset / 2;
   468
   469      return_trace (true);
   470    }
